var unsubscribed = new UnsubscribeList();
var pipeline = new DispatchPipeline(templates, unsubscribed);
var message = new Message
{
    Channel = Channel.Email,
    Subject = "welcome",
    Body = "Hello",
    Recipient = new Recipient
    {
        EmailAddress = "user@example.com",
        Phone = ""
    }
};

var result = pipeline.Run(message, 0);

Check.Equal("sent:8", result);

var templates = new RecordingTemplateStore("unused-template");
var unsubscribed = new UnsubscribeList();
var pipeline = new DispatchPipeline(templates, unsubscribed);
var message = new Message
{
    Channel = Channel.Email,
    Subject = "unused",
    Body = "",
    Recipient = new Recipient
    {
        EmailAddress = "",
        Phone = ""
    }
};

var result = pipeline.Run(message, 0);

Check.Equal("empty body", result);
Check.Equal(0, templates.Lookups.Count);

var belowTemplates = new RecordingTemplateStore("T");
var belowPipeline = new DispatchPipeline(belowTemplates, new UnsubscribeList());
var belowMessage = new Message
{
    Channel = Channel.Email,
    Subject = "notice",
    Body = "abc",
    Recipient = new Recipient { EmailAddress = "user@example.com", Phone = "" }
};

var atTemplates = new RecordingTemplateStore("T");
var atPipeline = new DispatchPipeline(atTemplates, new UnsubscribeList());
var atMessage = new Message
{
    Channel = Channel.Email,
    Subject = "notice",
    Body = "abc",
    Recipient = new Recipient { EmailAddress = "user@example.com", Phone = "" }
};

var aboveTemplates = new RecordingTemplateStore("T");
var abovePipeline = new DispatchPipeline(aboveTemplates, new UnsubscribeList());
var aboveMessage = new Message
{
    Channel = Channel.Email,
    Subject = "notice",
    Body = "abc",
    Recipient = new Recipient { EmailAddress = "user@example.com", Phone = "" }
};

var belowResult = belowPipeline.Run(belowMessage, 4);
var atResult = atPipeline.Run(atMessage, 5);
var aboveResult = abovePipeline.Run(aboveMessage, 6);

Check.Equal("retry:4:4", belowResult);
Check.Equal("retry:5:4", atResult);
Check.Equal("throttled", aboveResult);

var templates = new RecordingTemplateStore("IGNORED");
var unsubscribed = new UnsubscribeList();
var pipeline = new DispatchPipeline(templates, unsubscribed);
var message = new Message
{
    Channel = Channel.Sms,
    Subject = "sms-key",
    Body = "Ping",
    Recipient = new Recipient
    {
        EmailAddress = "",
        Phone = "12345"
    }
};

var result = pipeline.Run(message, 0);

Check.Equal("sent:4", result);

var templates = new RecordingTemplateStore(null);
var unsubscribed = new UnsubscribeList();
var pipeline = new DispatchPipeline(templates, unsubscribed);
var message = new Message
{
    Channel = Channel.Email,
    Subject = "missing",
    Body = "Content",
    Recipient = new Recipient
    {
        EmailAddress = "user@example.com",
        Phone = ""
    }
};

var result = pipeline.Run(message, 0);

Check.SequenceEqual(new[] { "missing" }, templates.Lookups);
Check.Equal("no template", result);
